function serializeSections(sections) {
  if (!isPlainObject(sections)) {
    throw new TypeError("sections must be an ordinary object");
  }

  const pairs = [];

  for (const section of Object.keys(sections)) {
    const sectionValue = sections[section];

    if (sectionValue === undefined) {
      continue;
    }

    if (!isPlainObject(sectionValue)) {
      throw new TypeError("section values must be ordinary objects");
    }

    const encodedSection = encodeRFC3986(section);

    for (const field of Object.keys(sectionValue)) {
      const values = sectionValue[field];

      if (values === undefined) {
        continue;
      }

      const encodedField = encodeRFC3986(field);

      if (!Array.isArray(values)) {
        throw new TypeError("field values must be arrays");
      }

      const encodedName =
        encodedSection + "%5B" + encodedField + "%5D";

      for (let index = 0; index < values.length; index++) {
        if (!Object.prototype.hasOwnProperty.call(values, index)) {
          throw new TypeError("field arrays must be dense");
        }

        const value = values[index];

        if (typeof value !== "string") {
          throw new TypeError("field array elements must be strings");
        }

        pairs.push({
          name: encodedName,
          value: encodeRFC3986(value)
        });
      }
    }
  }

  pairs.sort((left, right) => {
    if (left.name < right.name) return -1;
    if (left.name > right.name) return 1;
    if (left.value < right.value) return -1;
    if (left.value > right.value) return 1;
    return 0;
  });

  return pairs.map(pair => pair.name + "=" + pair.value).join("&");
}

function isPlainObject(value) {
  if (value === null || typeof value !== "object") {
    return false;
  }

  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}

function encodeRFC3986(value) {
  return encodeURIComponent(value).replace(/[!'()*]/g, character =>
    "%" + character.charCodeAt(0).toString(16).toUpperCase()
  );
}
